// ---- story (chapter Ch8 part 8a, ch8a agent: Sapphire's story scripts of this room; generators must keep
// everything from this line on; entries above marked "// story:")
// Sapphire data/maps/LilycoveCity_Harbor/scripts.inc. Owned by Ch13 (the S.S. Tidal): 8a places the people and
// writes the sailor. The ferry attendant is Ch13's: write scenes/LilycoveCity_Harbor_Ch13.inc with the label
// Ch13_LH_FerryAttendant (Sapphire's LilycoveCity_Harbor_EventScript_FerryAttendant: S.S. Ticket / Eon Ticket, Slateport
// and Battle Tower); it is included automatically. Until it exists the attendant says Sapphire's line for a harbor
// without a ferry (T_FerryUnavailable = text line 1; Ch13 appends its lines after line 3). Objects 2 (the S.S. Tidal,
// FLAG_HIDE_SS_TIDAL_LILYCOVE_HARBOR) and 4 (the ferry sailor of the Eon Ticket scene, FLAG_HIDE_FERRY_SAILOR_LILYCOVE)
// have no sprite / no script: Ch13 places them. The escape warp (setescapewarp) does not apply to Black 2's
// rooms. People: data/story/ch8a.json (attendant script = entry 2 below, the sailor entry 3).
#define T_FerryUnavailable 1
#define T_SailorUnavailable 2
#define T_SailorAvailable 3
#if __has_include("scenes/LilycoveCity_Harbor_Ch13.inc")
#include "scenes/LilycoveCity_Harbor_Ch13.inc"
#else
Ch13_LH_FerryAttendant:                     // LilycoveCity_Harbor_EventScript_FerryAttendant, before the game is cleared
    h_msgbox_npc T_FerryUnavailable
Ch13_LH_ArriveFromSlateport:
Ch13_LH_ArriveFromTower:
Ch13_LH_ArriveFromIsland:
    VMHalt
#endif
#if !__has_include("scenes/LilycoveCity_Harbor_Events.inc")
Ev_LH_Init:                                 // (events agent's zone init: scenes/LilycoveCity_Harbor_Events.inc)
    VMHalt
#endif

LH_Sailor:                                  // LilycoveCity_Harbor_EventScript_Sailor
    c3_talk
    h_goto_if_set FLAG_SYS_GAME_CLEAR, L_LH_FerryAvailable
    h_msgbox T_SailorUnavailable
    h_release
L_LH_FerryAvailable:
    h_msgbox T_SailorAvailable
    h_release
    .balign 4, 0
